            if c in [0, 1, 2]:
                row.append(9)
            elif 4 <= c <= 13:
                row.append(9)
        else:
            # Bottom section
            if 0 <= c <= 2:
                row.append(3) if r <= 5 else (6 if r <= 8 else 0)
            elif c == 3:
                row.append(4) if r <= 5 else (6 if r <= 8 else 0)
